<div class="space-y-6"><div class="flex items-center justify-between"><div><h1 class="text-2xl font-bold">Platform advertisements</h1><p class="text-sm text-gray-500">Timed image or video adverts shown automatically after login.</p></div><button wire:click="create" class="rounded bg-green-700 px-4 py-2 text-white">+ New advertisement</button></div>@if(session('success'))<div class="rounded bg-green-50 p-3 text-green-800">{{session('success')}}</div>@endif <div class="grid gap-4 md:grid-cols-2">@forelse($ads as $ad)<div class="card p-4"><b>{{$ad->title}}</b><p class="mt-1 text-sm text-gray-600">{{implode(', ',$ad->audiences)}} · Skip after {{$ad->skip_after_seconds}}s</p><p class="mt-1 text-xs text-gray-500">{{$ad->starts_at?->format('d M Y H:i') ?? 'Immediate'}} to {{$ad->ends_at?->format('d M Y H:i') ?? 'Until disabled'}}</p><button wire:click="toggle({{$ad->id}})" class="mt-3 text-sm text-green-700">{{$ad->is_active?'Disable':'Enable'}}</button></div>@empty<p>No advertisements yet.</p>@endforelse</div>@if($showForm)<div class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"><form wire:submit="save" class="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded bg-white p-6 space-y-3"><h2 class="text-lg font-bold">New advertisement</h2><input wire:model="title" class="w-full rounded border p-2" placeholder="Advertisement title"><textarea wire:model="message" rows="3" class="w-full rounded border p-2" placeholder="Optional message"></textarea><label>Image or video<input wire:model="media" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" class="mt-1 block"></label><label>Audience<select wire:model="audience" class="mt-1 w-full rounded border p-2"><option value="all">All users</option><option value="school-admin">School administrators</option><option value="teacher">Teachers</option><option value="parent">Parents</option><option value="student">Students</option><option value="bursar">Bursars</option></select></label><label>Seconds before skip<input wire:model="skipAfterSeconds" type="number" min="0" max="120" class="mt-1 w-full rounded border p-2"></label><div class="grid grid-cols-2 gap-3"><label>Start<input wire:model="startsAt" type="datetime-local" class="mt-1 w-full rounded border p-2"></label><label>End<input wire:model="endsAt" type="datetime-local" class="mt-1 w-full rounded border p-2"></label></div>@if($errors->any())<p class="text-sm text-red-600">{{$errors->first()}}</p>@endif<div class="flex gap-3"><button class="rounded bg-green-700 px-4 py-2 text-white">Publish</button><button type="button" wire:click="$set('showForm',false)">Cancel</button></div></form></div>@endif</div>
